import unittest

class Contract(unittest.TestCase):
    def test_contract(self):
        import graph as m
        data = {'c': ['a', 'b'], 'b': [], 'a': []}
        before = {k: list(v) for k, v in data.items()}
        self.assertEqual(m.order(data), ['a', 'b', 'c'])
        self.assertEqual(data, before)
        self.assertEqual(m.order({}), [])
        with self.assertRaises(Exception) as caught: m.order({'a': ['x']})
        self.assertIsInstance(caught.exception, KeyError)
        with self.assertRaises(Exception) as caught: m.order({'a': ['b'], 'b': ['a']})
        self.assertIsInstance(caught.exception, ValueError)
